//#region src/utils/index.ts
async function calculateSidebar(options) {
	const { docRoot, lang, sidebar: sidebarOptions, processIndexMd } = options;
	const sidebar = generateSidebar({
		documentRootPath: lang ? `/${lang}` : "/",
		resolvePath: lang ? `/${lang}/` : "/",
		useTitleFromFileHeading: true,
		useFolderTitleFromIndexFile: true,
		useFolderLinkFromIndexFile: true,
		sortMenusOrderNumericallyFromLink: true,
		...sidebarOptions
	});
	const loopSidebar = async (sidebarItems) => {
		for (const item of sidebarItems) {
			if (item.link && lang) item.link = joinURL(`/${lang}`, item.link);
			if (item.link?.endsWith("/index.md")) {
				const filePath = path.join(docRoot, item.link);
				let fileContent = "";
				try {
					fileContent = await fs.readFile(filePath, "utf8");
				} catch {
					continue;
				}
				checkMdFile(filePath, fileContent);
				if (splitLines(fileContent).filter(Boolean).length < 2 && processIndexMd) delete item.link;
			} else {
				const filePath = path.join(docRoot, `${item.link}.md`);
				let fileContent = "";
				try {
					fileContent = await fs.readFile(filePath, "utf8");
				} catch {
					continue;
				}
				checkMdFile(filePath, fileContent);
			}
			if (item.items) await loopSidebar(item.items);
		}
	};
	await loopSidebar(sidebar);
	return sidebar;
}
function checkMdFile(filePath, fileContent) {
	if (cheerio.load(`<body>${fileContent}</body>`)("a[id]").length > 0) {
		console.log(`${ansis.yellow(`(!) Found ${ansis.cyan("<a id=\"...\"></a>")} in file`)} ${filePath}`);
		throw new Error(`[${name}] checkMdFile not pass`);
	}
}
function generateCopyright() {
	return `Copyright © ${(/* @__PURE__ */ new Date()).getFullYear()}-present Agilebot Robotics Co., Ltd.`;
}

//#endregion
//#region src/pdf/index.ts
function extractLinksFromSidebar(sidebar) {
	const links = [];
	const extractLinks = (sidebar$1) => {
		for (const item of sidebar$1) {
			if (item.link) links.push(`${item.link.replace(/\.md$/, "")}.html`);
			if (item.items) extractLinks(item.items);
		}
	};
	extractLinks(sidebar);
	return links;
}
async function exportPdf(options) {
	const { docRoot, lang, onBeforePdfExport, onAfterPdfExport, ...rest } = options;
	const cacheDir = findCacheDir({
		name: ".vitepress-agilebot-pdf",
		create: true
	});
	assert.ok(cacheDir, "Failed to find cache directory");
	assert.ok(rest.outFile, "outFile is required");
	const { userConfig: vitepressConfig, outDir: vitepressOutDir } = await resolveConfig(docRoot);
	const outDir = path.relative(process.cwd(), vitepressOutDir);
	const docRootRel = path.isAbsolute(docRoot) ? path.relative(process.cwd(), docRoot) : docRoot;
	const routeOrder = extractLinksFromSidebar(await calculateSidebar({
		docRoot,
		lang,
		processIndexMd: false
	}));
	const headerTemplate = `<div style="margin-top: -0.4cm; height: 70%; width: 100%; display: flex; justify-content: center; align-items: center; color: lightgray; border-bottom: solid lightgray 1px; font-size: 10px;">
  <span class="title"></span>
</div>`;
	const footerTemplate = `<div style="margin-bottom: -0.4cm; height: 70%; width: 100%; display: flex; justify-content: flex-start; align-items: center; color: lightgray; border-top: solid lightgray 1px; font-size: 10px;">
  <span style="margin-left: 15px;">${generateCopyright()}</span>
</div>`;
	const config = {
		outFile: rest.outFile,
		outDir,
		routePatterns: [
			"!/",
			"!/index.html",
			...rest.routePatterns ?? []
		],
		pdfOptions: {
			format: "A4",
			printBackground: true,
			displayHeaderFooter: true,
			headerTemplate,
			footerTemplate,
			margin: {
				bottom: 60,
				left: 25,
				right: 25,
				top: 60
			}
		},
		sorter: (pageA, pageB) => {
			return routeOrder.indexOf(pageA.path) - routeOrder.indexOf(pageB.path);
		},
		puppeteerLaunchOptions: { args: [`--user-agent=${userAgentString} Puppeteer/22`] }
	};
	const langs = Object.values(vitepressConfig.locales ?? {}).map((locale) => locale.lang);
	if (langs.length > 0) config.routePatterns?.push(...langs.filter((o) => o !== lang).map((o) => `!/${o}/**`));
	const configContent = `
const routeOrder = ${JSON.stringify(routeOrder, null, 2)};

export default ${serialize(config, {
		space: 2,
		unsafe: true
	})}
`;
	const configPath = path.join(cacheDir, "pdf-export.config.js");
	await fs.writeFile(configPath, configContent);
	const cliPath = path.join(url.fileURLToPath(resolve("vitepress-export-pdf", import.meta.url)), "../../bin/press-export-pdf.mjs");
	await x(process.execPath, [
		cliPath,
		"export",
		docRootRel,
		"-c",
		configPath
	], { nodeOptions: { stdio: "inherit" } });
	const pdfOutFile = path.join(outDir, rest.outFile);
	const pdfContent = await fs.readFile(pdfOutFile);
	const pdfDoc = await PDFDocument.load(new Uint8Array(pdfContent));
	pdfDoc.registerFontkit(fontkit);
	const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
	const pages = pdfDoc.getPages();
	const totalPages = pages.length;
	for (let i = 0; i < totalPages; i++) {
		const page = pages[i];
		const { width } = page.getSize();
		const text = `${i + 1} / ${totalPages}`;
		const fontSize = 9;
		const textX = width - 50;
		const textY = fontSize;
		page.drawText(text, {
			x: textX,
			y: textY + 5,
			size: fontSize,
			font: helveticaFont,
			color: rgb(127 / 256, 127 / 256, 127 / 256)
		});
	}
	await onBeforePdfExport?.(pdfDoc);
	const newPdfContent = await pdfDoc.save();
	await fs.writeFile(pdfOutFile, newPdfContent);
	onAfterPdfExport?.(pdfOutFile);
}

//#endregion
export { exportPdf };